function loadStarterIdeas() {
  const saved = loadLocal("postly-ideas", starterIdeas);
  if (!Array.isArray(saved)) return starterIdeas.map(idea => ({ ...idea }));
  return saved.filter(idea => idea && typeof idea === "object" && typeof idea.title === "string").map(idea => {
    const previous = previousStarterIdeas[idea.id];
    const current = starterIdeas.find(seed => seed.id === idea.id);
    if (previous && current && idea.title === previous.title && idea.body === previous.body) return { ...idea, title: current.title, body: current.body };
    return { ...idea, id: typeof idea.id === "string" ? idea.id : crypto.randomUUID() };
  });
}
function parseStartPageLinks(value = "") {
  const entries = value.split(/\r?\n/).map(entry => entry.trim()).filter(Boolean);
  if (entries.length > 20) throw new Error("Add up to 20 social links.");
  return entries.map(entry => {
    const url = new URL(entry);
    if (url.protocol !== "https:" || !url.hostname) throw new Error("Use one full HTTPS link per line.");
    return { label: url.hostname.replace(/^www\./i, ""), url: url.href };
  });
}
